#!/usr/bin/env node
/**
 * Rebuilds test/fixtures/db/schema-<tag>.sql — the database a member's phone held after
 * running a PAST release (audit QA-04 / harness H8). Read-only on git: for each tag it reads
 * that release's own source with `git show <tag>:…`, replays exactly the DDL that release ran
 * at start-up (src/db/schema.ts, then the tracker and member migrations it had) into a real
 * SQLite (sql.js), and dumps the resulting schema plus the version stamps in `meta`.
 *
 * Run from apps/mobile when a new schema version ships (add its tag to TAGS):
 *   node test/fixtures/db/make-schema-fixtures.mjs
 * The output is committed; test/db/migrations.test.ts loads it.
 */
import { execFileSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import initSqlJs from 'sql.js';

// Oldest release with a database (v0.2.0; v0.1.0 had none), then one per distinct schema
// state worth proving: tracker v2 (pre-onboarding, demo auto-seeded), tracker v2 + member v1
// (first real-member build), tracker v5 (exercise library columns), tracker v7 (folders),
// and the latest release (tracker v8) — whose upgrade must be a no-op.
const TAGS = ['v0.2.0', 'v0.9.0', 'v0.21.0', 'v0.24.0', 'v0.27.0', 'v0.29.1'];

const HERE = dirname(fileURLToPath(import.meta.url));

function show(tag, path) {
  try {
    return execFileSync('git', ['show', `${tag}:apps/mobile/${path}`], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  } catch {
    return null;
  }
}

/** The ordered DDL steps a migration function ran (ensureColumn → ALTER, execAsync → SQL). */
function migrationSteps(src, fnName) {
  if (!src) return { version: 0, steps: [] };
  const version = Number(/_SCHEMA_VERSION = (\d+)/.exec(src)?.[1] ?? 0);
  const body = src.slice(src.indexOf(`export async function ${fnName}`));
  const steps = [];
  const re = /ensureColumn\('(\w+)',\s*'(\w+)',\s*'([^']+)'\)|execAsync\(\s*(?:`([\s\S]*?)`|'([^']*)')/g;
  for (const m of body.matchAll(re)) {
    if (m[1]) steps.push({ table: m[1], column: m[2], decl: m[3] });
    else steps.push({ sql: m[4] ?? m[5] });
  }
  return { version, steps };
}

function columnExists(db, table, column) {
  const r = db.exec(`PRAGMA table_info(${table})`)[0];
  return !!r && r.values.some((v) => v[1] === column);
}

const SQL = await initSqlJs();

for (const tag of TAGS) {
  const schemaSrc = show(tag, 'src/db/schema.ts');
  if (!schemaSrc) throw new Error(`${tag}: no src/db/schema.ts`);
  const ddl = /export const DDL = `([\s\S]*?)`;/.exec(schemaSrc)[1];
  const schemaVersion = /SCHEMA_VERSION = (\d+)/.exec(schemaSrc)[1];
  const tracker = migrationSteps(show(tag, 'src/tracker/db/trackerSchema.ts'), 'initTrackerSchema');
  const member = migrationSteps(show(tag, 'src/onboarding/db/memberSchema.ts'), 'initMemberSchema');

  const db = new SQL.Database();
  db.exec(ddl);
  db.run("INSERT INTO meta(key, value) VALUES('schema_version', ?)", [schemaVersion]);
  for (const s of [...tracker.steps, ...member.steps]) {
    if (s.sql) db.exec(s.sql);
    else if (!columnExists(db, s.table, s.column)) db.exec(`ALTER TABLE ${s.table} ADD COLUMN ${s.column} ${s.decl}`);
  }
  if (tracker.version) db.run("INSERT INTO meta(key, value) VALUES('tracker_schema_version', ?)", [String(tracker.version)]);
  if (member.version) db.run("INSERT INTO meta(key, value) VALUES('member_schema_version', ?)", [String(member.version)]);

  const objects = db.exec("SELECT sql FROM sqlite_master WHERE sql IS NOT NULL ORDER BY rowid")[0].values.map((v) => v[0]);
  const meta = db.exec('SELECT key, value FROM meta ORDER BY rowid')[0].values;
  const out = [
    `-- GENERATED by make-schema-fixtures.mjs from git tag ${tag} — do not edit by hand.`,
    `-- The database a phone held after running ${tag}: base schema v${schemaVersion},`,
    `-- tracker schema v${tracker.version}, member schema v${member.version}. No member rows: the test adds them.`,
    ...objects.map((s) => `${s};`),
    ...meta.map(([k, v]) => `INSERT INTO meta(key, value) VALUES('${k}', '${v}');`),
    '',
  ].join('\n');
  writeFileSync(join(HERE, `schema-${tag}.sql`), out);
  console.log(`${tag}: tracker v${tracker.version}, member v${member.version}, ${objects.length} objects`);
  db.close();
}
